  /* ══════════════════ สรุปเนื้อหาบทเรียน (เนื้อหากฎหมายจริง — ทยอยเพิ่มทีละวิชา/ทีละบรรพ) ══════════════════
     markdown-lite แบบเดียวกับที่ classroom-business.html/classroom-engineering.html ใช้ (พอร์ตมาเป็น ES5
     เพราะไฟล์นี้เป็น vanilla JS ไม่ใช่ React) — esc() มีอยู่แล้วด้านบนของไฟล์ ใช้ escape ก่อนแปลง markdown
     เสมอกัน XSS จากเนื้อหาที่อาจมีเครื่องหมาย <, >, & ปนอยู่ */
  function mdInline(t) {
    return t
      .replace(/`([^`]+)`/g, '<code>$1</code>')
      .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
      .replace(/\*([^*]+)\*/g, '<em>$1</em>')
      .replace(/==([^=]+)==/g, '<mark>$1</mark>');
  }
  function mdToHtml(src) {
    var html = '', inUl = false, inOl = false;
    function closeLists() {
      if (inUl) { html += '</ul>'; inUl = false; }
      if (inOl) { html += '</ol>'; inOl = false; }
    }
    esc(src || '').split('\n').forEach(function (raw) {
      var l = raw.replace(/\s+$/, '');
      if (/^###\s/.test(l)) { closeLists(); html += '<h4>' + mdInline(l.slice(4)) + '</h4>'; }
      else if (/^##\s/.test(l)) { closeLists(); html += '<h3>' + mdInline(l.slice(3)) + '</h3>'; }
      else if (/^#\s/.test(l)) { closeLists(); html += '<h2>' + mdInline(l.slice(2)) + '</h2>'; }
      else if (/^[-*]\s/.test(l)) {
        if (!inUl) { closeLists(); html += '<ul>'; inUl = true; }
        html += '<li>' + mdInline(l.slice(2)) + '</li>';
      }
      else if (/^\d+\.\s/.test(l)) {
        if (!inOl) { closeLists(); html += '<ol>'; inOl = true; }
        html += '<li>' + mdInline(l.replace(/^\d+\.\s/, '')) + '</li>';
      }
      else if (l === '') closeLists();
      else { closeLists(); html += '<p>' + mdInline(l) + '</p>'; }
    });
    closeLists();
    return html;
  }

